package com.example.fashgo.ui.screens.products
import android.app.Application
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.viewModelScope
import com.example.fashgo.data.remote.RemoteProductRepository
import com.example.fashgo.data.remote.RemoteSalesRepository
import com.example.fashgo.data.remote.model.Producto
import com.example.fashgo.util.ProductCodeGenerator
import com.example.fashgo.util.ProductDraft
import kotlinx.coroutines.flow.*
import kotlinx.coroutines.launch
import java.util.UUID
data class ProductUiState(val isLoading:Boolean=false,val error:String?=null,val success:String?=null,val selectedProduct:Producto?=null,val suggestedCode:String="")
class ProductViewModel(application:Application):AndroidViewModel(application){
 private val _ui=MutableStateFlow(ProductUiState());val uiState=_ui.asStateFlow();private val _query=MutableStateFlow("");val searchQuery=_query.asStateFlow()
 val products=combine(RemoteProductRepository.products,_query){list,q->if(q.isBlank())list else list.filter{p->q.lowercase().split(' ').all{"${p.nombre} ${p.tipo} ${p.color} ${p.talla} ${p.codigoProducto} ${p.ubicacion}".lowercase().contains(it)}}}.stateIn(viewModelScope,SharingStarted.WhileSubscribed(5000),emptyList())
 val lowStockProducts=RemoteProductRepository.products.map{it.filter{p->p.stock<=p.stockMinimo}}.stateIn(viewModelScope,SharingStarted.WhileSubscribed(5000),emptyList())
 val noMovementProducts=combine(RemoteProductRepository.products,RemoteSalesRepository.sales,RemoteSalesRepository.details){all,sales,details->val recentSaleIds=sales.filter{it.estadoContable=="confirmada"&&it.fecha>=System.currentTimeMillis()-30L*86_400_000}.map{it.id}.toSet();val moved=details.filter{it.ventaId in recentSaleIds}.map{it.productoId}.toSet();all.filter{it.id !in moved}}.stateIn(viewModelScope,SharingStarted.WhileSubscribed(5000),emptyList())
 val abcByProductId=combine(RemoteProductRepository.products,RemoteSalesRepository.sales,RemoteSalesRepository.details){all,sales,details->val valid=sales.filter{it.estadoContable=="confirmada"&&it.fecha>=System.currentTimeMillis()-15L*86_400_000}.map{it.id}.toSet();val sold=details.filter{it.ventaId in valid}.groupBy{it.productoId}.mapValues{it.value.sumOf{d->d.cantidad}};val ordered=all.filter{(sold[it.id]?:0)>0}.sortedByDescending{sold[it.id]?:0};val top=ordered.take(kotlin.math.ceil(ordered.size/3.0).toInt()).map{it.id}.toSet();all.associate{it.id to if(it.id in top)"A" else if((sold[it.id]?:0)>0)"B" else "C"}}.stateIn(viewModelScope,SharingStarted.WhileSubscribed(5000),emptyMap())
 init{refresh()};private fun refresh()=viewModelScope.launch{try{_ui.value=_ui.value.copy(isLoading=true);RemoteProductRepository.refresh();RemoteSalesRepository.refresh()}catch(e:Exception){_ui.value=_ui.value.copy(error=e.message)}finally{_ui.value=_ui.value.copy(isLoading=false)}}
 fun onSearchQueryChange(v:String){_query.value=v};fun loadProduct(id:String){_ui.value=_ui.value.copy(selectedProduct=RemoteProductRepository.byId(id),suggestedCode=RemoteProductRepository.byId(id)?.codigoProducto.orEmpty())}
 fun updateSuggestedCode(parteGeneral:String,tipo:String,diseno:String,tipoManga:String,tipoCuello:String,color:String,talla:String){val d=ProductDraft(parteGeneral,tipo,diseno,tipoManga,tipoCuello,color,talla);if(listOf(parteGeneral,tipo,color,talla).any{it.isBlank()}){_ui.value=_ui.value.copy(suggestedCode="");return};val prefix=ProductCodeGenerator.buildPrefix(d);_ui.value=_ui.value.copy(suggestedCode=ProductCodeGenerator.buildCode(d,RemoteProductRepository.products.value.map{it.codigoProducto}.filter{it.startsWith("$prefix-")}))}
 fun saveProduct(id:String?,parteGeneral:String,tipo:String,diseno:String,tipoManga:String,tipoCuello:String,color:String,talla:String,precio:String,stock:String,ubicacion:String,stockMinimo:String,onSuccess:()->Unit){val price=precio.toDoubleOrNull();val qty=stock.toIntOrNull();if(parteGeneral.isBlank()||tipo.isBlank()||color.isBlank()||talla.isBlank()||price==null||price<=0||qty==null||qty<0||ubicacion.isBlank()){_ui.value=_ui.value.copy(error="Completa los datos válidos y la ubicación");return};val draft=ProductDraft(parteGeneral,tipo,diseno,tipoManga,tipoCuello,color,talla);val old=id?.let(RemoteProductRepository::byId);val code=old?.codigoProducto?:_ui.value.suggestedCode.ifBlank{ProductCodeGenerator.buildCode(draft,RemoteProductRepository.products.value.map{it.codigoProducto})};val p=Producto(id?:UUID.randomUUID().toString(),ProductCodeGenerator.buildName(draft),parteGeneral,tipo,diseno,tipoManga,tipoCuello,color,talla,price,old?.stock?:qty,old?.stockReferencia?:qty,old?.ubicacion?:ubicacion,code,code,stockMinimo.toIntOrNull()?:3);viewModelScope.launch{try{_ui.value=_ui.value.copy(isLoading=true,error=null);RemoteProductRepository.save(p,qty,ubicacion);RemoteProductRepository.refresh();onSuccess()}catch(e:Exception){_ui.value=_ui.value.copy(error=e.message)}finally{_ui.value=_ui.value.copy(isLoading=false)}}}
 fun deleteProduct(p:Producto,onSuccess:()->Unit)=viewModelScope.launch{try{RemoteProductRepository.deactivate(p.id);RemoteProductRepository.refresh();onSuccess()}catch(e:Exception){_ui.value=_ui.value.copy(error=e.message)}}
 fun clearMessages(){_ui.value=_ui.value.copy(error=null,success=null)}
}
